"""Ilustrações do pop-up 'Você ganhou!', recortadas da imagem de referência enviada pelo Gabriel (mascote comemorando, estrela, troféu, moedas).
Cada item: (WebP em base64, largura, altura). Módulo só de dados."""
from __future__ import annotations

IMAGENS = {
    "mascote": ("", 420, 291),
    "estrela": ("", 96, 90),
    "trofeu": ("", 90, 100),
    "moedas": ("", 100, 90),
}


def uri(nome: str) -> str:
    d = IMAGENS.get(nome)
    return f"data:image/webp;base64,{d[0]}" if d else ""


def existe(nome: str) -> bool:
    return nome in IMAGENS
